import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './RegistrationForm.css';

function Login() {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });

  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const springResponse = await axios.post('/users/login', formData);
      
      if (springResponse.data === 'Login successful') {
        // Get user details from Spring Boot
        const userResponse = await axios.get('/users/findByEmail', {
          params: { email: formData.email }
        });
        
        if (userResponse.data) {
          // Store complete user data locally
          localStorage.setItem('userEmail', formData.email);
          localStorage.setItem('user', JSON.stringify(userResponse.data));
          localStorage.setItem('userId', userResponse.data.id);

          // Also store user preferences and settings
          if (!localStorage.getItem('dietTrackerUserData')) {
            const defaultUserData = {
              username: userResponse.data.username,
              email: userResponse.data.email,
              health: {
                weight: parseFloat(userResponse.data.weight),
                targetWeight: parseFloat(userResponse.data.desiredWeight),
                height: userResponse.data.height,
                activityLevel: "Moderate"
              },
              weightHistory: [{
                date: new Date().toLocaleString('default', { month: 'short' }),
                weight: parseFloat(userResponse.data.weight)
              }]
            };
            localStorage.setItem('dietTrackerUserData', JSON.stringify(defaultUserData));
          }
          
          navigate('/homepage');
        }
      }
    } catch (error) {
      setErrors({ login: error.response?.data || 'Error logging in' });
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Login</h2>
      <div>
        <label>Email:</label>
        <input
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          placeholder="Enter your email"
        />
        {errors.email && <p className="error">{errors.email}</p>}
      </div>
      <div>
        <label>Password:</label>
        <input
          type="password"
          name="password"
          value={formData.password}
          onChange={handleChange}
          placeholder="Enter your password"
        />
        {errors.password && <p className="error">{errors.password}</p>}
      </div>
      <button type="submit">Login</button>
      <p>Don't have an account? <a href="/">Create one here</a></p>
    </form>
  );
}

export default Login;
